(function(){'use strict';const S=window.KERN_SHAPES,E=window.KERN_ELEVATIONS;
const snapValue=(v,free)=>free?v:Math.round(v/.25)*.25;
function surface(plan,fid,p,exclude){const f=plan.floors[fid],r=f.rooms.find(r=>r.id!==exclude&&!r.localSteps&&!isStair(r,fid)&&!['void','solid'].includes(r.type)&&S.contains(p,r));return r?{kind:'room',floor:fid,room:r.id}:{kind:'site'};}
function begin(mode,fid,p,sourceId,width=1.4){const source=model.floors[fid]?.rooms.find(r=>r.id===sourceId),g={mode,fid,start:{x:p.x,y:p.y},width:Math.max(1,Math.min(10,width)),scope:currentBuilding().id};if(mode==='edge-steps'){if(!source||source.localSteps||isStair(source,fid)||!canEdit(source))return{error:'Select a room and drag from one of its edges'};const edge=S.edges(source).filter(e=>!e.curved).map(e=>({...e,d:S.project(p,e).distance})).sort((a,b)=>a.d-b.d)[0];if(!edge)return{error:'Choose a straight room edge'};if(edge.d>.75)return{error:'Click near the room edge, then drag outward'};if(Math.abs(edge.a[0]-edge.b[0])>.001&&Math.abs(edge.a[1]-edge.b[1])>.001)return{error:'Steps from edge currently need a grid-aligned edge'};const dx=edge.b[0]-edge.a[0],dy=edge.b[1]-edge.a[1],len=Math.hypot(dx,dy),sign=S.areaOf(S.points(source))>=0?1:-1,t={x:dx/len,y:dy/len},n={x:t.y*sign,y:-t.x*sign},w=Math.min(g.width,len),along=Math.max(w/2,Math.min(len-w/2,(p.x-edge.a[0])*t.x+(p.y-edge.a[1])*t.y));Object.assign(g,{source:source.id,width:w,normal:n,anchor:{x:edge.a[0]+t.x*along,y:edge.a[1]+t.y*along}});}return g;}
function candidate(g,p,free=false){if(g.error)return g;if(g.scope!==currentBuilding().id||!model.floors[g.fid])return{error:'The building or floor changed'};const fid=g.fid,f=model.floors[fid],a=g.start,r={id:'__3d_room_preview__',name:g.mode==='room'?'Room':'Local steps',type:g.mode==='room'?'tech':'terrace',x:0,y:0,w:1,h:1};let start,end,axis,landingEnd;
if(g.mode==='edge-steps'){const run=Math.max(0,snapValue((p.x-g.anchor.x)*g.normal.x+(p.y-g.anchor.y)*g.normal.y,free));if(run<1)return{error:'Drag outward at least 1 m'};const b={x:g.anchor.x+g.normal.x*run,y:g.anchor.y+g.normal.y*run};axis=Math.abs(g.normal.x)>.5?'x':'y';landingEnd=axis==='x'?(g.normal.x>0?'west':'east'):(g.normal.y>0?'north':'south');Object.assign(r,axis==='x'?{x:Math.min(g.anchor.x,b.x),y:g.anchor.y-g.width/2,w:run,h:g.width}:{x:g.anchor.x-g.width/2,y:Math.min(g.anchor.y,b.y),w:g.width,h:run});start={kind:'room',floor:fid,room:g.source};end=surface(model,fid,b,g.source);
}else{const x1=snapValue(a.x,free),y1=snapValue(a.y,free),x2=snapValue(p.x,free),y2=snapValue(p.y,free);Object.assign(r,{x:Math.min(x1,x2),y:Math.min(y1,y2),w:Math.abs(x2-x1),h:Math.abs(y2-y1)});if(r.w<1||r.h<1)return{error:'Draw at least 1 × 1 m'};axis=Math.abs(x2-x1)>=Math.abs(y2-y1)?'x':'y';const forward=axis==='x'?x2>=x1:y2>=y1;landingEnd=axis==='x'?(forward?'west':'east'):(forward?'north':'south');const p0=axis==='x'?{x:forward?r.x:r.x+r.w,y:r.y+r.h/2}:{x:r.x+r.w/2,y:forward?r.y:r.y+r.h},p1=axis==='x'?{x:forward?r.x+r.w:r.x,y:r.y+r.h/2}:{x:r.x+r.w/2,y:forward?r.y+r.h:r.y};start=surface(model,fid,p0);end=surface(model,fid,p1);}
if([r.x,r.y].some(v=>Math.abs(v)>150)||r.w>150||r.h>150)return{error:'Keep the footprint within plan limits'};if(g.mode==='room')return{room:r,fid,scope:g.scope,summary:r.w.toFixed(2)+' × '+r.h.toFixed(2)+' m'};
const z0=E.value(model,start,f.z),z1=E.value(model,end,E.ground(model));if(Math.abs(z1-z0)<.01)return{error:'Both ends are at the same height; connect two different surfaces'};Object.assign(r,{outdoor:true,localSteps:true,stairTransition:true,stairType:'straight',runAxis:axis,landingEnd});const c={id:'__3d_link_preview__',room:r.id,floor:fid,localSteps:true,stairType:'straight',runAxis:axis,landingEnd,start,end,lowerZ:z0,upperZ:z1,targetRiser:.17},plan=clone(model);plan.floors[fid].rooms.push(r);plan.splitLevelConnections??=[];plan.splitLevelConnections.push(c);E.sync(plan);const detail=E.build(plan,fid,r.id);return{room:r,connection:c,detail,fid,scope:g.scope,summary:detail.segments[0].risers+' rises · '+Math.abs(z1-z0).toFixed(2)+' m · '+(detail.metrics.treadDepth*100).toFixed(0)+' cm tread'+(detail.warnings.length?' · '+detail.warnings[0].text:'')};}
function finish(q){if(!q||q.error){notify(q?.error||'Draw a footprint first');return false;}if(q.scope!==currentBuilding().id||!model.floors[q.fid])return false;if(model.floors[q.fid].rooms.length>=300){notify('This floor has reached its room limit');return false;}floorId=q.fid;document.body.classList.add('editing3d');commit(()=>{const r=clone(q.room);r.id=uniqueId(r.localSteps?'localsteps-':'room-');model.floors[q.fid].rooms.push(r);if(q.connection){const c=clone(q.connection);c.id=uniqueId('local-link-');c.room=r.id;model.splitLevelConnections??=[];model.splitLevelConnections.push(c);model.siteGroundZ=E.ground(model);E.sync(model);}setSelection({rooms:[r.id]});});return true;}
window.KERN_AUTHORING_3D={begin,candidate,finish};
})();
